import { ethers } from 'ethers';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import dotenv from 'dotenv';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
dotenv.config({ path: path.join(__dirname, '..', '.env.local') });

// Contract ABIs
const BSTN_ABI = [
  'constructor()',
  'function transferOwnership(address newOwner) external',
  'function mint(address to, uint256 amount) external',
  'function name() external view returns (string)',
  'function symbol() external view returns (string)',
  'function totalSupply() external view returns (uint256)',
  'event Transfer(address indexed from, address indexed to, uint256 value)',
  'event OwnershipTransferred(address indexed previousOwner, address indexed newOwner)',
];

const BSTN_BYTECODE = '';

const CLAIM_ABI = [
  'constructor(address _bstnToken)',
  'function setSnapshot(address[] memory users, uint256[] memory xpAmounts) external',
  'function claim() external',
  'function claimable(address user) external view returns (uint256)',
  'function claimed(address user) external view returns (bool)',
];

const CLAIM_BYTECODE = '

 ';

async function deployBSTN(signer) {
  console.log('📦 Step 1: Deploying BSTN Token...');
  
  const factory = new ethers.ContractFactory(BSTN_ABI, BSTN_BYTECODE, signer);
  const contract = await factory.deploy();
  const tx = await contract.deploymentTransaction();
  const receipt = await tx.wait();
  
  const address = await contract.getAddress();
  console.log(`✅ BSTN deployed to: ${address}\n`);
  
  return address;
}

async function deployClaim(signer, bstnAddress) {
  console.log('📦 Step 2: Deploying BSTNClaim...');
  
  const factory = new ethers.ContractFactory(CLAIM_ABI, CLAIM_BYTECODE, signer);
  const contract = await factory.deploy(bstnAddress);
  const tx = await contract.deploymentTransaction();
  const receipt = await tx.wait();
  
  const address = await contract.getAddress();
  console.log(`✅ BSTNClaim deployed to: ${address}\n`);
  
  return address;
}

async function main() {
  console.log('\n🚀 Deploying BSTN Token & Claims System...\n');

  const privateKey = process.env.PRIVATE_KEY_DEPLOYER;
  if (!privateKey) {
    throw new Error('PRIVATE_KEY_DEPLOYER not found in .env.local');
  }

  const provider = new ethers.JsonRpcProvider('https://mainnet.base.org');
  const signer = new ethers.Wallet(privateKey, provider);
  
  const signerAddress = signer.address;
  const balance = await provider.getBalance(signerAddress);

  console.log(`📝 Deployer: ${signerAddress}`);
  console.log(`💰 Balance: ${ethers.formatEther(balance)} ETH\n`);

  if (ethers.parseEther('0.01') > balance) {
    throw new Error('Not enough ETH for gas (~0.01 ETH required)');
  }

  try {
    // Read contract bytecode from files
    let bstnBytecode, claimBytecode;
    
    try {
      const bstnPath = path.join(__dirname, '..', 'artifacts', 'contracts', 'BSTN.sol', 'BSTN.json');
      const bstnArtifact = JSON.parse(fs.readFileSync(bstnPath, 'utf-8'));
      bstnBytecode = bstnArtifact.bytecode;
    } catch (e) {
      console.log('⚠️  Using fallback BSTN bytecode...');
      bstnBytecode = '';
    }

    try {
      const claimPath = path.join(__dirname, '..', 'artifacts', 'contracts', 'BSTNClaim.sol', 'BSTNClaim.json');
      const claimArtifact = JSON.parse(fs.readFileSync(claimPath, 'utf-8'));
      claimBytecode = claimArtifact.bytecode;
    } catch (e) {
      console.log('⚠️  Using fallback BSTNClaim bytecode...');
      claimBytecode = '';
    }

    // Deploy BSTN
    console.log('📦 Step 1: Deploying BSTN Token...');
    const bstnFactory = new ethers.ContractFactory(BSTN_ABI, bstnBytecode, signer);
    const bstn = await bstnFactory.deploy();
    const bstnTx = await bstn.deploymentTransaction();
    if (bstnTx) {
      await bstnTx.wait();
    }
    const bstnAddress = await bstn.getAddress();
    console.log(`✅ BSTN deployed to: ${bstnAddress}\n`);

    // Deploy BSTNClaim
    console.log('📦 Step 2: Deploying BSTNClaim...');
    const claimFactory = new ethers.ContractFactory(CLAIM_ABI, claimBytecode, signer);
    const claim = await claimFactory.deploy(bstnAddress);
    const claimTx = await claim.deploymentTransaction();
    if (claimTx) {
      await claimTx.wait();
    }
    const claimAddress = await claim.getAddress();
    console.log(`✅ BSTNClaim deployed to: ${claimAddress}\n`);

    // Transfer ownership
    console.log('📦 Step 3: Granting mint permissions...');
    const bstnContract = new ethers.Contract(bstnAddress, BSTN_ABI, signer);
    const ownerTx = await bstnContract.transferOwnership(claimAddress);
    await ownerTx.wait();
    console.log(`✅ Ownership transferred\n`);

    // Update .env.local
    console.log('📝 Step 4: Updating .env.local...');
    const envPath = path.join(__dirname, '..', '.env.local');
    let envContent = fs.readFileSync(envPath, 'utf-8');

    if (envContent.includes('NEXT_PUBLIC_BSTN_TOKEN=')) {
      envContent = envContent.replace(/NEXT_PUBLIC_BSTN_TOKEN=.*/, `NEXT_PUBLIC_BSTN_TOKEN=${bstnAddress}`);
    } else {
      envContent += `\nNEXT_PUBLIC_BSTN_TOKEN=${bstnAddress}`;
    }

    if (envContent.includes('NEXT_PUBLIC_BSTN_CLAIM=')) {
      envContent = envContent.replace(/NEXT_PUBLIC_BSTN_CLAIM=.*/, `NEXT_PUBLIC_BSTN_CLAIM=${claimAddress}`);
    } else {
      envContent += `\nNEXT_PUBLIC_BSTN_CLAIM=${claimAddress}`;
    }

    fs.writeFileSync(envPath, envContent);
    console.log('✅ .env.local updated\n');

    console.log('🎉 DEPLOYMENT COMPLETE\n');
    console.log('📋 Contract Addresses:');
    console.log(`   BSTN Token:  ${bstnAddress}`);
    console.log(`   BSTNClaim:   ${claimAddress}\n`);

  } catch (error) {
    console.error('❌ Deployment failed:', error.message);
    throw error;
  }
}

main()
  .then(() => process.exit(0))
  .catch((error) => {
    console.error(error);
    process.exit(1);
  });
